import os
from google.cloud import vision

def extract_key_value_pairs_from_form(image_path):
    client = vision.ImageAnnotatorClient()
    with open(image_path, 'rb') as image_file:
        content = image_file.read()
    image = vision.Image(content=content)
    response = client.document_text_detection(image=image)
    document = response.full_text_annotation

    key_value_pairs = {}
    for page in document.pages:
        for block in page.blocks:
            for paragraph in block.paragraphs:
                for word in paragraph.words:
                    text = ''.join(symbol.text for symbol in word.symbols)
                    if 'Date of Birth' in text:
                        key = 'Date of Birth'
                    elif 'Social Security Number' in text:
                        key = 'Social Security Number'
                    elif 'Address' in text:
                        key = 'Address'
                    else:
                        continue

                    value = next((paragraph for paragraph in block.paragraphs if text in paragraph.text), None)
                    if value:
                        text = ''.join(symbol.text for symbol in value.words)
                        key_value_pairs[key] = text

    return key_value_pairs
